{"sql":"CREATE OR REPLACE PROCEDURE employees.generate_monthly_report(report_date DATE)
LANGUAGE plpgsql
AS $$
DECLARE
    dept_count INT;
    tot_emps INT;
    avg_sal DECIMAL;
    rep_id INT;
BEGIN
    SELECT COUNT(*) INTO dept_count FROM employees.department;

    SELECT COUNT(DISTINCT e.id) INTO tot_emps
    FROM employees.employee e
    JOIN employees.salary s ON e.id = s.employee_id
    WHERE s.to_date = '9999-01-01';

    SELECT AVG(s.amount) INTO avg_sal
    FROM employees.salary s
    WHERE s.to_date = '9999-01-01';

    INSERT INTO employees.monthly_reports (report_date, department_count, total_employees, avg_salary, generated_at)
    VALUES (report_date, dept_count, tot_emps, avg_sal, CURRENT_TIMESTAMP)
